let MUSK = -1;
function musicFor(k) { /* 0 = spelmuziek (titel, kaart, stad), 1 = gevechtsmuziek */
  if (k === MUSK) return; MUSK = k;
  try { if (typeof __music === 'function') __music(k); } catch (e) {}
  try { if (typeof webMusic === 'function') webMusic(k); } catch (e) {}
}
function render() {
  musicFor(ui.mode === 'battle' ? 1 : 0);
  if (ui.mode === 'title') { drawTitleTop(); drawTitleBottom(); return; }
  if (ui.mode === 'pick') { drawPickTop(); drawPickBottom(); return; }
  if (ui.mode === 'end') { drawEndTop(); drawEndBottom(); return; }
  if (ui.mode === 'battle') { drawBattleTop(); drawBattleBottom(); }
  else { if (castleOpen()) { drawTown(); const ov = overlayTop(); if (ov) tc.drawImage(ov, 0, 0); else { vignette(tc, 400, 240); frame(tc, 400, 240); } } else { drawTop(); vignette(tc, 400, 240); } drawBottom(); }
}

/* ============ BEDIENING (later: D-pad, knoppen en touchscreen) ============ */
function step(dx, dy) {
  if (ui.mode === 'battle') return;
  const was = Rules.onCastle();
  Rules.move(dx, dy);
  if (!was && Rules.onCastle()) { ui.remote = false; ui.panel = 'castle'; Rules.s.hero.sp = maxSp(Rules.s.hero); }
  if (Rules.s.fight) { Battle.start(Rules.s.fight); Rules.s.fight = null; ui.mode = 'battle'; stopHold(); setTimeout(() => { render(); pump(); }, 0); }
}
addEventListener('keydown', e => {
  if (ui.mode !== 'map') return;
  const k = e.key.toLowerCase();
  const m = { arrowup: [0, -1], w: [0, -1], arrowdown: [0, 1], s: [0, 1], arrowleft: [-1, 0], a: [-1, 0], arrowright: [1, 0], d: [1, 0] }[k];
  if (m) { e.preventDefault(); ui.path = null; ui.cam = null; step(m[0], m[1]); render(); }
  else if (k === 'e') { Rules.endTurn(); render(); }
});
cvBot.addEventListener('pointerdown', e => {
  const r = cvBot.getBoundingClientRect(), b = 6;
  const x = (e.clientX - r.left - b) * 320 / (r.width - 2 * b), y = (e.clientY - r.top - b) * 240 / (r.height - 2 * b);
  const hit = buttons.find(q => x >= q.x && x < q.x + q.w && y >= q.y && y < q.y + q.h);
  if (hit) {
    hit.on(); render();
    if (hit.repeat) {
      stopHold();
      holdStart = setTimeout(() => { hold = setInterval(() => { hit.on(); render(); }, 130); }, 350);
    }
  } else if (ui.mode === 'battle') battleTap(x, y);
  else if (ui.mode === 'map' && mapBox && x >= mapBox.x && y >= mapBox.y && x < mapBox.x + mapBox.w && y < mapBox.y + mapBox.h) { ui.dragMini = true; miniCam(e); }
});
