['pointerup', 'pointerleave', 'pointercancel'].forEach(t => cvBot.addEventListener(t, stopHold));

/* ===== Muziek (alleen waar geluid bestaat; op de 3DS wordt dit overgeslagen) ===== */
const MUS = { on: true, el: [null, null], k: 0 };
