if (HAS_AUDIO) {
  document.addEventListener('pointerdown', musicSync);
  document.addEventListener('pointerdown', sfxInit);
  document.addEventListener('visibilitychange', musicSync);
  document.addEventListener('keydown', e => { if ((e.key || '').toLowerCase() === 'm') { toggleMusic(); render(); } });
  const _dtb = drawTitleBottom;
  function toggleSfx() { SFXC.on = !SFXC.on; try { localStorage.setItem('crownfall_sfx', SFXC.on ? '1' : '0'); } catch (e) {} sfxInit(); sfx('tick'); }
  drawTitleBottom = function () { _dtb(); const y0 = ui.hasSave ? 154 : 126; button('Muziek: ' + (MUS.on ? 'aan' : 'uit'), 50, y0, 220, 28, () => toggleMusic(), true); button('Effecten: ' + (SFXC.on ? 'aan' : 'uit'), 50, y0 + 32, 220, 28, () => toggleSfx(), true); };
}

